// Factory-owned acceptance tests for bonus-library-ai-cover-openai. The builder must make
// these pass and cannot edit them. The owner chose OpenAI gpt-image-2 after a test
// (realistic 3D mockups with the exact title; about US$0.06 per image).
//   src/lib/ai-cover.ts exports AI_COVER_MODEL "gpt-image-2", AI_COVER_PROVIDER_URL
//     "https://api.openai.com/v1/images/generations", AI_COVER_PROMPT_VERSION 2,
//     AI_COVER_STYLES and AI_COVER_STYLE_LABELS (unchanged), AI_COVER_MAX_IMAGE_BYTES
//     8 MiB, and AI_COVER_REGION "us-west-2" (kept until the wiring task removes Bedrock).
//   buildCoverRequest(title, style) returns null for invalid input (as before) or exactly
//     { model, prompt, size, quality: "medium", n: 1 }: size "1024x1536" for ebook and
//     "1024x1024" for software_box. The prompt asks for a professional 3D product mockup
//     photo (a hardcover book standing upright, or a retail software box at a
//     three-quarter angle) on a clean light background, shows the trimmed title in double
//     quotes exactly once with double quotes in the title replaced by single quotes, says
//     "spelled exactly", and forbids people and other words. At most 1000 characters.
//   parseCoverResponse accepts exactly { data: [{ b64_json }] } (other fields allowed in
//     the item) holding strict base64 of a PNG of at most 8 MiB; otherwise null.
//   src/lib/ai-cover-budget.ts: AI_COVER_RESERVE_MICRO_USD 100_000; coverGenerationId also
//     hashes AI_COVER_PROMPT_VERSION (one fresh attempt per owner, item and style for the
//     new prompt); coverReservationTransaction accepts only a request equal in shape to
//     buildCoverRequest output for that style and records AI_COVER_MODEL.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { AI_COVER_MAX_IMAGE_BYTES, AI_COVER_MODEL, AI_COVER_PROMPT_VERSION, AI_COVER_PROVIDER_URL,
  AI_COVER_STYLE_LABELS, AI_COVER_STYLES, buildCoverRequest, parseCoverResponse } from '../../src/lib/ai-cover.ts';
import { AI_COVER_RESERVE_MICRO_USD, coverGenerationId, coverReservationTransaction } from '../../src/lib/ai-cover-budget.ts';

const OWNER = '11111111-1111-4111-8111-111111111111';
const ITEM = '22222222-2222-4222-8222-222222222222';
const PNG = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 1, 2, 3]);

test('pinned OpenAI provider and limits', () => {
  assert.equal(AI_COVER_MODEL, 'gpt-image-2');
  assert.equal(AI_COVER_PROVIDER_URL, 'https://api.openai.com/v1/images/generations');
  assert.equal(AI_COVER_PROMPT_VERSION, 2);
  assert.equal(AI_COVER_MAX_IMAGE_BYTES, 8 * 1024 * 1024);
  assert.deepEqual([...AI_COVER_STYLES], ['ebook', 'software_box']);
  assert.deepEqual({ ...AI_COVER_STYLE_LABELS }, { ebook: 'eBook cover', software_box: 'Software box' });
  assert.equal(AI_COVER_RESERVE_MICRO_USD, 100_000);
});

test('mockup requests carry the exact title once', () => {
  const book = buildCoverRequest('  Streaming Profits Authority  ', 'ebook');
  assert.deepEqual(Object.keys(book).sort(), ['model', 'n', 'prompt', 'quality', 'size']);
  assert.deepEqual([book.model, book.size, book.quality, book.n], ['gpt-image-2', '1024x1536', 'medium', 1]);
  assert.match(book.prompt, /3D product mockup/i);
  assert.match(book.prompt, /hardcover book/i);
  assert.equal(book.prompt.split('"Streaming Profits Authority"').length - 1, 1);
  assert.match(book.prompt, /spelled exactly/i);
  assert.match(book.prompt, /no people/i);
  assert.match(book.prompt, /no other words/i);
  const box = buildCoverRequest('Pixel Studio Pro', 'software_box');
  assert.equal(box.size, '1024x1024');
  assert.match(box.prompt, /software box/i);
  assert.match(box.prompt, /three-quarter/i);
  assert.equal(box.prompt.split('"Pixel Studio Pro"').length - 1, 1);
  assert.ok(buildCoverRequest('Say "Hi"', 'ebook').prompt.includes(`"Say 'Hi'"`));
  for (const [title, style] of [['', 'ebook'], ['x'.repeat(121), 'ebook'], ['Atlas', 'poster'], ['A\u0007', 'ebook'], [5, 'ebook']]) {
    assert.equal(buildCoverRequest(title, style), null);
  }
  for (const style of AI_COVER_STYLES) {
    assert.ok(buildCoverRequest('x'.repeat(120), style).prompt.length <= 1000);
  }
});

test('only a single safe PNG in the OpenAI response is accepted', () => {
  const ok = parseCoverResponse({ data: [{ b64_json: Buffer.from(PNG).toString('base64'), revised_prompt: 'x' }], created: 1 });
  assert.deepEqual([...ok.bytes], [...PNG]);
  assert.equal(ok.mediaType, 'image/png');
  for (const body of [null, {}, { data: [] }, { data: [{}, {}] }, { data: [{ b64_json: 'bm90IGEgcG5n' }] },
    { data: [{ b64_json: 'not base64!' }] }, { data: [{ url: 'https://example.invalid/x.png' }] }]) {
    assert.equal(parseCoverResponse(body), null, JSON.stringify(body));
  }
});

test('the improved prompt gives one fresh attempt and reserves US$0.10', () => {
  const id = coverGenerationId(OWNER, ITEM, 'ebook');
  assert.notEqual(id, createHash('sha256').update(`${OWNER}\n${ITEM}\nebook`, 'utf8').digest('hex'));
  assert.equal(coverGenerationId(OWNER, ITEM, 'ebook'), id);
  const request = buildCoverRequest('Atlas', 'ebook');
  const tx = coverReservationTransaction(id, OWNER, ITEM, 'ebook', request, 1_800_000_000, 'a'.repeat(40));
  const [{ Update: update }, { Put: put }] = tx.TransactItems;
  assert.ok(JSON.stringify(update.ExpressionAttributeValues).includes('100000'));
  assert.ok(JSON.stringify(update.ExpressionAttributeValues).includes('1900000'));
  assert.deepEqual(put.Item.reserved_micro_usd, { N: '100000' });
  assert.deepEqual(put.Item.model, { S: 'gpt-image-2' });
  assert.deepEqual(JSON.parse(put.Item.request.S), request);
  for (const bad of [{ ...request, size: '1024x1024' }, { ...request, extra: 1 },
    { prompt: 'p', negative_prompt: 'n', aspect_ratio: '2:3', output_format: 'png' }]) {
    assert.throws(() => coverReservationTransaction(id, OWNER, ITEM, 'ebook', bad, 1_800_000_000, 'a'.repeat(40)));
  }
});

// Factory-owned acceptance tests for bonus-library-ai-cover-openai (replaces the ai-cover-service acceptance tests for the OpenAI response format). The builder must
// make these pass and cannot edit them. Contract: src/lib/ai-cover-service.ts exports
//   coverObjectPath(owner, item, id) -> `${owner}/${item}-ai-cover-${id.slice(0, 16)}.png`
//     (owner and item UUIDs, id 64 lowercase hex; throws otherwise).
//   coverGenerationEnabled(env) -> true only when VERCEL_ENV is "production",
//     VERCEL_GIT_COMMIT_SHA is 40 lowercase hex and BONUS_AI_COVER_ACTIVATION_SHA equals it.
//   generateCover({ owner, item, title, style }, backend, enabled) where backend has
//     load(id), availability(), reserve(id, owner, item, style, request),
//     invoke(body: string) -> parsed JSON, store(owner, item, id, bytes) -> object path,
//     finish(id, objectPath, sha256). Order: load first and return any saved record
//     unchanged (never invoke twice for one id, including a "reserved" record whose outcome
//     is unknown); then throw unless enabled and availability().enabled; build the request
//     with buildCoverRequest (throw if null); reserve; invoke JSON.stringify(request) once;
//     parseCoverResponse (throw if null, attempt stays consumed); store; finish with the
//     lowercase hex SHA-256 of the bytes; return
//     { status: "generated", style, object_path, sha256 }.
//   coverRequest(request, { authorize, backend, env }) HTTP handler. authorize(item) returns
//     { owner, title } or null. Every reply has Cache-Control "private, no-store".
//     GET ?item=<uuid>&style=<style>: 400 if invalid; 403 if not authorized; when
//     env.BONUS_AI_COVER_ROLE_ARN is unset or VERCEL_ENV is not production:
//     { enabled: false, reason: "paused", saved: null }; a saved record:
//     { enabled: false, reason: "saved", saved }; otherwise paused unless
//     coverGenerationEnabled(env), else { ...availability, saved: null }.
//     POST: 405 for other methods; 403 unless Origin is https://bonus-library.vercel.app;
//     JSON body exactly { item_id, style } else 400; 403 if not authorized; 409 when not
//     configured; otherwise { saved: await generateCover(...) }; any failure 409 with a
//     fixed message that never includes error text.
import test from 'node:test';
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { coverGenerationId } from '../../src/lib/ai-cover-budget.ts';
import { coverGenerationEnabled, coverObjectPath, coverRequest, generateCover } from '../../src/lib/ai-cover-service.ts';

const OWNER = '11111111-1111-4111-8111-111111111111';
const ITEM = '22222222-2222-4222-8222-222222222222';
const COMMIT = 'c'.repeat(40);
const ENV = { VERCEL_ENV: 'production', VERCEL_GIT_COMMIT_SHA: COMMIT, BONUS_AI_COVER_ACTIVATION_SHA: COMMIT,
  BONUS_AI_COVER_ROLE_ARN: 'arn:aws:iam::666730517561:role/example' };
const PNG = Uint8Array.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a, 1, 2, 3]);
const IMAGE = { data: [{ b64_json: Buffer.from(PNG).toString('base64') }] };

function backend({ saved = null, ready = true, response = IMAGE } = {}) {
  const calls = [];
  return { calls,
    async load(id) { calls.push(['load', id]); return saved; },
    async availability() { calls.push(['availability']); return { enabled: ready, reason: ready ? 'ready' : 'limit' }; },
    async reserve(...args) { calls.push(['reserve', ...args]); },
    async invoke(body) { calls.push(['invoke', body]); return response; },
    async store(owner, item, id, bytes) { calls.push(['store', owner, item, id, bytes.length]); return coverObjectPath(owner, item, id); },
    async finish(...args) { calls.push(['finish', ...args]); } };
}

test('object path and activation gate', () => {
  const id = coverGenerationId(OWNER, ITEM, 'ebook');
  assert.equal(coverObjectPath(OWNER, ITEM, id), `${OWNER}/${ITEM}-ai-cover-${id.slice(0, 16)}.png`);
  assert.throws(() => coverObjectPath('x', ITEM, id));
  assert.throws(() => coverObjectPath(OWNER, ITEM, 'abc'));
  assert.equal(coverGenerationEnabled(ENV), true);
  for (const change of [{ VERCEL_ENV: 'preview' }, { BONUS_AI_COVER_ACTIVATION_SHA: 'd'.repeat(40) },
    { VERCEL_GIT_COMMIT_SHA: 'main', BONUS_AI_COVER_ACTIVATION_SHA: 'main' }, { BONUS_AI_COVER_ACTIVATION_SHA: undefined }]) {
    assert.equal(coverGenerationEnabled({ ...ENV, ...change }), false, JSON.stringify(change));
  }
});

test('generates once: reserve, one invocation, store, finish', async () => {
  const fake = backend();
  const id = coverGenerationId(OWNER, ITEM, 'software_box');
  const saved = await generateCover({ owner: OWNER, item: ITEM, title: 'Dragon Atlas', style: 'software_box' }, fake, true);
  const sha = createHash('sha256').update(PNG).digest('hex');
  const path = coverObjectPath(OWNER, ITEM, id);
  assert.deepEqual(saved, { status: 'generated', style: 'software_box', object_path: path, sha256: sha });
  assert.deepEqual(fake.calls.map(c => c[0]), ['load', 'availability', 'reserve', 'invoke', 'store', 'finish']);
  assert.equal(fake.calls[0][1], id);
  const reserve = fake.calls[2];
  assert.deepEqual(reserve.slice(1, 5), [id, OWNER, ITEM, 'software_box']);
  assert.equal(reserve[5].size, '1024x1024');
  assert.deepEqual(JSON.parse(fake.calls[3][1]), reserve[5]);
  assert.deepEqual(fake.calls[5].slice(1), [id, path, sha]);
});

test('a saved or unknown-outcome record is returned without another paid call', async () => {
  for (const saved of [{ status: 'reserved', style: 'ebook' },
    { status: 'generated', style: 'ebook', object_path: 'x', sha256: 'y' }]) {
    const fake = backend({ saved });
    assert.deepEqual(await generateCover({ owner: OWNER, item: ITEM, title: 'Atlas', style: 'ebook' }, fake, true), saved);
    assert.deepEqual(fake.calls.map(c => c[0]), ['load']);
  }
});

test('disabled, unavailable, invalid title or invalid image never store a cover', async () => {
  const cases = [[backend(), false, 'Atlas'], [backend({ ready: false }), true, 'Atlas'], [backend(), true, '   '],
    [backend({ response: { data: [{ b64_json: 'bm90IGEgcG5n' }] } }), true, 'Atlas']];
  for (const [fake, enabled, title] of cases) {
    await assert.rejects(generateCover({ owner: OWNER, item: ITEM, title, style: 'ebook' }, fake, enabled));
    assert.ok(!fake.calls.some(c => c[0] === 'store' || c[0] === 'finish'));
    assert.ok(fake.calls.filter(c => c[0] === 'invoke').length <= 1);
  }
});

const ORIGIN = 'https://bonus-library.vercel.app';
const authorize = async (item) => item === ITEM ? { owner: OWNER, title: 'Dragon Atlas' } : null;
const get = (query) => new Request(`${ORIGIN}/api/cover?${query}`);
const post = (body, origin = ORIGIN) => new Request(`${ORIGIN}/api/cover`, { method: 'POST',
  headers: { 'content-type': 'application/json', origin }, body: typeof body === 'string' ? body : JSON.stringify(body) });

test('GET reports saved, paused or availability', async () => {
  let response = await coverRequest(get(`item=${ITEM}&style=ebook`), { authorize, backend: () => backend(), env: ENV });
  assert.equal(response.headers.get('cache-control'), 'private, no-store');
  assert.deepEqual(await response.json(), { enabled: true, reason: 'ready', saved: null });
  response = await coverRequest(get(`item=${ITEM}&style=ebook`), { authorize, backend: () => backend({ ready: false }), env: ENV });
  assert.deepEqual(await response.json(), { enabled: false, reason: 'limit', saved: null });
  const saved = { status: 'generated', style: 'ebook', object_path: 'p', sha256: 's' };
  response = await coverRequest(get(`item=${ITEM}&style=ebook`), { authorize, backend: () => backend({ saved }), env: { ...ENV, BONUS_AI_COVER_ACTIVATION_SHA: undefined } });
  assert.deepEqual(await response.json(), { enabled: false, reason: 'saved', saved });
  response = await coverRequest(get(`item=${ITEM}&style=ebook`), { authorize, backend: () => backend(), env: { ...ENV, BONUS_AI_COVER_ACTIVATION_SHA: undefined } });
  assert.deepEqual(await response.json(), { enabled: false, reason: 'paused', saved: null });
  response = await coverRequest(get(`item=${ITEM}&style=ebook`), { authorize, backend: () => { throw new Error('no'); }, env: { ...ENV, BONUS_AI_COVER_ROLE_ARN: undefined } });
  assert.deepEqual(await response.json(), { enabled: false, reason: 'paused', saved: null });
  assert.equal((await coverRequest(get(`item=${ITEM}&style=poster`), { authorize, backend: () => backend(), env: ENV })).status, 400);
  assert.equal((await coverRequest(get('item=33333333-3333-4333-8333-333333333333&style=ebook'), { authorize, backend: () => backend(), env: ENV })).status, 403);
});

test('POST generates only for an authorized same-origin exact request', async () => {
  const fake = backend();
  let response = await coverRequest(post({ item_id: ITEM, style: 'ebook' }), { authorize, backend: () => fake, env: ENV });
  assert.equal(response.status, 200);
  assert.equal((await response.json()).saved.status, 'generated');
  assert.equal(response.headers.get('cache-control'), 'private, no-store');
  const deps = { authorize, backend: () => backend(), env: ENV };
  assert.equal((await coverRequest(post({ item_id: ITEM, style: 'ebook' }, 'https://evil.example'), deps)).status, 403);
  assert.equal((await coverRequest(post({ item_id: ITEM, style: 'ebook', extra: 1 }), deps)).status, 400);
  assert.equal((await coverRequest(post('not json'), deps)).status, 400);
  assert.equal((await coverRequest(post({ item_id: '33333333-3333-4333-8333-333333333333', style: 'ebook' }), deps)).status, 403);
  assert.equal((await coverRequest(post({ item_id: ITEM, style: 'ebook' }), { ...deps, env: { ...ENV, VERCEL_ENV: 'preview' } })).status, 409);
  assert.equal((await coverRequest(new Request(`${ORIGIN}/api/cover`, { method: 'DELETE' }), deps)).status, 405);
  response = await coverRequest(post({ item_id: ITEM, style: 'ebook' }), { authorize,
    backend: () => backend({ response: { secret: 'provider text' } }), env: ENV });
  assert.equal(response.status, 409);
  assert.ok(!(await response.text()).includes('provider text'));
});

// Factory-owned acceptance tests for bonus-library-ai-cover-openai (replaces the ai-cover-backend acceptance tests for the OpenAI request format). The builder must
// make these pass and cannot edit them. Contract: src/lib/ai-cover-backend.ts exports
//   createCoverBackend(deps) returning the CoverBackend used by generateCover in
//   ai-cover-service.ts. deps (all injected; the module imports no SDK):
//     getItem(input) -> { Item?: DynamoDB attribute map }
//     updateItem(input), transactWrite(input)
//     invokeModel({ modelId, contentType, accept, body }) -> Uint8Array response body
//     upload(path, bytes, contentType)
//     now() -> Unix seconds; commit (40 lowercase hex, else createCoverBackend throws)
//   Records live in AI_COVER_TABLE under PK AI_COVER_PARTITION; attempts use SK
//   "APP#<id>", the budget uses SK "BUDGET"; every read is ConsistentRead.
//   load(id): null when absent, else { status, style } plus object_path and sha256 when
//     stored.
//   availability(): coverBudgetAvailability of the BUDGET record (N -> number,
//     BOOL -> boolean, S -> string; null when absent) at now() for commit.
//   reserve(...): transactWrite(coverReservationTransaction(..., now(), commit)).
//   invoke(body): one invokeModel with modelId AI_COVER_MODEL and JSON content types;
//     the response must be at most 8 MiB of strict UTF-8 JSON (throws otherwise).
//   store(owner, item, id, bytes): upload(coverObjectPath(owner, item, id), bytes,
//     "image/png") and return that path.
//   finish(id, path, sha256): updateItem setting status "generated", object_path and
//     sha256 on APP#<id> only while its status is "reserved".
import test from 'node:test';
import assert from 'node:assert/strict';
import { AI_COVER_MODEL, buildCoverRequest } from '../../src/lib/ai-cover.ts';
import { AI_COVER_PARTITION, AI_COVER_TABLE, coverGenerationId } from '../../src/lib/ai-cover-budget.ts';
import { coverObjectPath } from '../../src/lib/ai-cover-service.ts';
import { createCoverBackend } from '../../src/lib/ai-cover-backend.ts';

const OWNER = '11111111-1111-4111-8111-111111111111';
const ITEM = '22222222-2222-4222-8222-222222222222';
const COMMIT = 'a'.repeat(40);
const NOW = 1_800_000_000;
const ID = coverGenerationId(OWNER, ITEM, 'ebook');
const budget = { app_enabled: { BOOL: true }, app_version: { S: 'bonus-ai-cover-app-v1' }, app_commit: { S: COMMIT },
  limit_micro_usd: { N: '2000000' }, reserved_micro_usd: { N: '0' }, dispatches: { N: '0' },
  app_dispatch_limit: { N: '40' }, app_expires_at: { N: String(NOW + 60) } };

function fake(items = {}, response = new TextEncoder().encode('{"images":["x"]}')) {
  const calls = [];
  const deps = { commit: COMMIT, now: () => NOW,
    async getItem(input) { calls.push(['getItem', input]); return { Item: items[input.Key.SK.S] }; },
    async updateItem(input) { calls.push(['updateItem', input]); return {}; },
    async transactWrite(input) { calls.push(['transactWrite', input]); return {}; },
    async invokeModel(input) { calls.push(['invokeModel', input]); return response; },
    async upload(...args) { calls.push(['upload', ...args]); } };
  return { calls, backend: createCoverBackend(deps) };
}

test('requires an exact commit', () => {
  assert.throws(() => createCoverBackend({ ...fake().backend, commit: 'main', now: () => NOW }));
});

test('load reads one consistent attempt record', async () => {
  let { calls, backend } = fake();
  assert.equal(await backend.load(ID), null);
  assert.deepEqual(calls[0][1], { TableName: AI_COVER_TABLE, ConsistentRead: true,
    Key: { PK: { S: AI_COVER_PARTITION }, SK: { S: `APP#${ID}` } } });
  ({ backend } = fake({ [`APP#${ID}`]: { status: { S: 'reserved' }, style: { S: 'ebook' } } }));
  assert.deepEqual(await backend.load(ID), { status: 'reserved', style: 'ebook' });
  ({ backend } = fake({ [`APP#${ID}`]: { status: { S: 'generated' }, style: { S: 'ebook' },
    object_path: { S: 'p.png' }, sha256: { S: 'f'.repeat(64) } } }));
  assert.deepEqual(await backend.load(ID), { status: 'generated', style: 'ebook', object_path: 'p.png', sha256: 'f'.repeat(64) });
});

test('availability converts the budget record', async () => {
  let { calls, backend } = fake({ BUDGET: budget });
  assert.deepEqual(await backend.availability(), { enabled: true, reason: 'ready' });
  assert.deepEqual(calls[0][1].Key, { PK: { S: AI_COVER_PARTITION }, SK: { S: 'BUDGET' } });
  assert.equal(calls[0][1].ConsistentRead, true);
  ({ backend } = fake({ BUDGET: { ...budget, app_expires_at: { N: String(NOW) } } }));
  assert.deepEqual(await backend.availability(), { enabled: false, reason: 'expired' });
  ({ backend } = fake());
  assert.deepEqual(await backend.availability(), { enabled: false, reason: 'paused' });
});

test('reserve, invoke, store and finish use the fixed records and model', async () => {
  const { calls, backend } = fake();
  const request = buildCoverRequest('Atlas', 'ebook');
  await backend.reserve(ID, OWNER, ITEM, 'ebook', request);
  const tx = calls[0][1];
  assert.equal(tx.TransactItems.length, 2);
  assert.ok(JSON.stringify(tx).includes(String(NOW)) && JSON.stringify(tx).includes(COMMIT));
  assert.deepEqual(await backend.invoke('{"prompt":"p"}'), { images: ['x'] });
  assert.deepEqual(calls[1][1], { modelId: AI_COVER_MODEL, contentType: 'application/json',
    accept: 'application/json', body: '{"prompt":"p"}' });
  const bytes = Uint8Array.from([1, 2, 3]);
  const path = await backend.store(OWNER, ITEM, ID, bytes);
  assert.equal(path, coverObjectPath(OWNER, ITEM, ID));
  assert.deepEqual(calls[2], ['upload', path, bytes, 'image/png']);
  await backend.finish(ID, path, 'e'.repeat(64));
  const update = calls[3][1];
  assert.equal(update.TableName, AI_COVER_TABLE);
  assert.deepEqual(update.Key, { PK: { S: AI_COVER_PARTITION }, SK: { S: `APP#${ID}` } });
  const text = JSON.stringify(update);
  for (const value of ['generated', 'reserved', path, 'e'.repeat(64), 'object_path', 'sha256']) assert.ok(text.includes(value), value);
  assert.match(update.ConditionExpression, /=/);
});

test('oversized or invalid model responses are rejected', async () => {
  await assert.rejects(fake({}, new TextEncoder().encode(`{"a":"${'x'.repeat(8 * 1024 * 1024)}"}`)).backend.invoke('{}'));
  await assert.rejects(fake({}, Uint8Array.from([0xff, 0xfe])).backend.invoke('{}'));
  await assert.rejects(fake({}, new TextEncoder().encode('not json')).backend.invoke('{}'));
});
